<?php
require_once __DIR__ . '/../includes/db.php';
require_once __DIR__ . '/../includes/auth.php';
requireLogin();
$templates = ['Modern'=>1, 'Professional'=>2, 'Simple'=>3, 'Creative'=>4, 'Student'=>5, 'Executive'=>6, 'Elegant'=>7, 'ATS Friendly'=>8];
$templateName = trim((string)($_GET['template'] ?? $_POST['template'] ?? 'Modern'));
if (!isset($templates[$templateName])) $templateName = 'Modern';
$error = '';
$values = ['title'=>'CV mới','full_name'=>'','job_title'=>'','email'=>'','phone'=>'','address'=>'','objective'=>'','school'=>'','major'=>'','education_period'=>'','company'=>'','job'=>'','work_period'=>'','experience'=>'','skills'=>'','languages'=>''];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 foreach ($values as $key=>$default) $values[$key] = trim((string)($_POST[$key] ?? $default));
 $templateName = trim((string)($_POST['template'] ?? 'Modern'));
 if (!isset($templates[$templateName])) $templateName='Modern';
 if ($values['title']==='') $error='Vui lòng nhập tên CV.';
 elseif ($values['full_name']==='') $error='Vui lòng nhập họ và tên.';
 else {
  $data = ['personal'=>['full_name'=>$values['full_name'],'job_title'=>$values['job_title'],'email'=>$values['email'],'phone'=>$values['phone'],'address'=>$values['address']], 'objective'=>$values['objective'], 'education'=>array_values(array_filter([['school'=>$values['school'],'major'=>$values['major'],'period'=>$values['education_period']]],fn($x)=>implode('', $x)!=='')), 'experience'=>array_values(array_filter([['company'=>$values['company'],'position'=>$values['job'],'period'=>$values['work_period'],'description'=>$values['experience']]],fn($x)=>implode('', $x)!=='')), 'skills'=>array_values(array_filter(array_map('trim',explode(',',$values['skills'])))), 'languages'=>array_values(array_filter(array_map('trim',explode(',',$values['languages']))))];
  $stmt=$pdo->prepare('INSERT INTO cvs (user_id,template_id,title,data) VALUES (?,?,?,?)');
  $stmt->execute([getCurrentUserId(),$templates[$templateName],$values['title'],json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
  $id=(int)$pdo->lastInsertId(); setFlashMessage('success','Đã lưu CV vào tài khoản của bạn.'); header('Location: preview.php?id='.$id); exit;
 }
}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
